// Pour AJOUTER un champ : ajoute une ligne { key: "nom_du_champ_api", label: "Libellé affiché" }.
// L'ordre de cette liste = l'ordre d'affichage à l'écran.
// ─────────────────────────────────────────────────────────────────────────
