const SelectionTextile = () => {
  const [items, setItems] = useState([]);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);

  const formatFieldValue = (value) => {
    if (Array.isArray(value)) {
      return value.join(", ");
    }

    if (value && typeof value === "object") {
      return Object.values(value).join(", ");
    }

    return String(value);
  };

  useEffect(() => {
    fetch("/api/products")
      .then((res) => {
        if (!res.ok) throw new Error("Erreur lors du chargement des données");
        return res.json();
      })
      .then((data) => {
        setItems(data.categories);
        setProducts(data.products);

        // SUPPRIMÉ :
        // setSelectedCategory(data.categories[0]?.id ?? null);

        setLoading(false);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  }, []);


  /* if (loading) return <SkeletonSelectionTextile />; */
  if (error) return <div>Erreur : {error}</div>;


  const filteredProducts = products.filter(
    (p) => p.category_id === selectedCategory
  );


  return (
    <div className="selection-textile">
      <h2>NOTRE CARGAISON</h2>
      <p className="selection-textile-description">Nos best-sellers pour étaler notre encre.</p>

          <div className="fournisseur-image">         <img src={fournisseur} alt="Fournisseur"  />
    </div>
      {/* <TextileList
        items={items}
        selectedCategory={selectedCategory}
        onSelect={setSelectedCategory}
      /> */}


      {selectedCategory && (
        <Swiper
          modules={[Navigation, Pagination]}
          slidesPerView={1.4}
          centeredSlides={false}
          spaceBetween={100}
          loop={filteredProducts.length > 1}
          navigation
          pagination={{ clickable: true }}
          className="textile-swiper"
          breakpoints={{
            0: { slidesPerView: 1, spaceBetween: 20 },
            768: { slidesPerView: 1.4, spaceBetween: 100 }
          }}
        >
          {filteredProducts.map((product) => (
            <SwiperSlide key={product.id}>
              <div className="full-card">

                <div className="card">
                  <img
                    src={product.image || "/images/placeholder.png"}
                    alt={product.name}
                    loading="lazy"
                    decoding="async"
                  />

                  <p>
                    <strong>{product.name}</strong>
                  </p>


                  {Array.isArray(product.colors) && product.colors.length > 0 && (
                    <div style={{
                      display: "flex",
                      gap: "0.5em",
                      margin: "0.5em 1rem"
                    }}>
                      {product.colors.map((color, idx) => (
                        <span
                          key={idx}
                          title={color}
                          style={{
                            display: "inline-block",
                            width: "1.5em",
                            height: "1.5em",
                            background: color,
                            border: "1px solid #ccc",
                            borderRadius: "50%",
                          }}
                        />
                      ))}
                    </div>
                  )}
                </div>


                <div className="card-description">

                  {product.reference && (
                    <p className="reference-line">
                      <strong>Réf : </strong>
                      <span>{product.reference}</span>
                    </p>
                  )}

                  {product.description && (
                    <p className="description-line">
                      <strong>Description : </strong>
                      <span>{product.description}</span>
                    </p>
                  )}


                  <div className="card-info">
                    <p className="info-line">
                      <strong>Infos</strong>
                    </p>

                    {INFO_FIELDS
                      .filter(({ key }) =>
                        product[key] !== undefined &&
                        product[key] !== null &&
                        product[key] !== ""
                      )
                      .map(({ key, label, icon }) => (
                        <p key={key} className="info-field">
                          {icon && (
                            <img
                              className="info-field-icon"
                              src={icon}
                              alt={label}
                            />
                          )}

                          <strong>{label} : </strong>
                          <span>
                            {formatFieldValue(product[key])}
                          </span>
                        </p>
                      ))}
                  </div>

                </div>

              </div>
            </SwiperSlide>
          ))}
        </Swiper>
      )}
      <p className="selection-textile-description selection-textile-description-muted">
        “No-label” et confection possible sur demande
      </p>
    </div>
  );
};

export default SelectionTextile;
